# Closed Arch bootstrap and Limine bootloader program.
# Arguments are validated scalars generated by Rust.
set -eu
fs=$1 esp_uuid=$2 boot_uuid=$3 root_uuid=$4 disk_uuid=$5 root_end=$6
for tool in mount umount findmnt pacstrap chroot blkid sgdisk grep sed awk cut tr sync mkdir chmod cp rm mv; do
    command -v "$tool" >/dev/null || { printf 'Missing runtime image tool: %s\n' "$tool" >&2; exit 1; }
done
record() { printf '%s\n' "$1" >> /receipt; sync -f /receipt; }
step() {
    id=$1
    if grep -q "^ok:$id$" /receipt; then probe_$id; return; fi
    if grep -q "^start:$id$" /receipt; then probe_$id; record "ok:$id"; return; fi
    record "start:$id"
    do_$id >&2
    probe_$id >&2
    record "ok:$id"
}
cleanup() {
    umount /target/boot/efi 2>/dev/null || :
    umount /target/boot 2>/dev/null || :
    umount /target/dev/pts 2>/dev/null || :
    umount /target/dev 2>/dev/null || :
    umount /target/proc 2>/dev/null || :
    umount /target/sys 2>/dev/null || :
    umount /target/run 2>/dev/null || :
    umount -R /target 2>/dev/null || :
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP

# Mount ground truth storage layout
if test "$fs" = btrfs; then
    mount -o subvol=@,compress=zstd /dev/borea-root /target
    for pair in '@home:home' '@snapshots:.snapshots' '@log:var/log' '@cache:var/cache'; do
        mkdir -p "/target/${pair#*:}"
        mount -o "subvol=${pair%%:*},compress=zstd" /dev/borea-root "/target/${pair#*:}"
    done
else
    mount /dev/borea-root /target
fi
mkdir -p /target/boot
mount /dev/borea-boot /target/boot
mkdir -p /target/boot/efi
mount /dev/borea-esp /target/boot/efi

probe_storage_probe() {
    test -f /target/etc/fstab
    grep -q "$root_uuid" /target/etc/fstab
    grep -q "$boot_uuid" /target/etc/fstab
    findmnt --mountpoint /target >/dev/null
    findmnt --mountpoint /target/boot >/dev/null
    findmnt --mountpoint /target/boot/efi >/dev/null
}
do_storage_probe() {
    probe_storage_probe
}

probe_pacstrap() {
    test -x /target/usr/bin/bash
    test -x /target/usr/bin/pacman
    test -d /target/usr/lib/modules
}
do_pacstrap() {
    # Ensure active mirrors are present
    mkdir -p /etc/pacman.d
    if ! grep -q '^[[:space:]]*Server[[:space:]]*=' /etc/pacman.d/mirrorlist 2>/dev/null; then
        cat << 'EOF' > /etc/pacman.d/mirrorlist
Server = https://geo.mirror.pkgbuild.com/$repo/os/$arch
Server = https://mirrors.kernel.org/archlinux/$repo/os/$arch
Server = https://mirror.rackspace.com/archlinux/$repo/os/$arch
EOF
    fi
    # Execute pacstrap for base system, kernel, tools, network and bootloader
    pacstrap -K -c /target \
        base \
        linux \
        linux-firmware \
        btrfs-progs \
        e2fsprogs \
        dosfstools \
        networkmanager \
        sudo \
        zram-generator \
        openssh \
        limine \
        efibootmgr
}

mount_chroot() {
    mkdir -p /target/proc /target/sys /target/dev /target/run
    mountpoint -q /target/proc || mount -t proc proc /target/proc
    mountpoint -q /target/sys || mount -t sysfs sys /target/sys
    mountpoint -q /target/dev || mount --bind /dev /target/dev
    mountpoint -q /target/run || mount --bind /run /target/run
    if [ -f /etc/resolv.conf ]; then
        cp -L /etc/resolv.conf /target/etc/resolv.conf
    fi
}

probe_system_config() {
    test -f /target/etc/hostname
    grep -q 'borea' /target/etc/hostname
    test -f /target/etc/locale.conf
    test -f /target/etc/sudoers.d/10-borea
    test -d /target/home/borea
}
do_system_config() {
    mount_chroot
    printf 'borea\n' > /target/etc/hostname
    cat << 'EOF' > /target/etc/hosts
127.0.0.1 localhost
::1       localhost
127.0.1.1 borea.localdomain borea
EOF
    if [ -f /target/etc/locale.gen ]; then
        sed -i 's/^#[[:space:]]*\(en_US\.UTF-8 UTF-8\)/\1/' /target/etc/locale.gen
        sed -i 's/^#[[:space:]]*\(en_GB\.UTF-8 UTF-8\)/\1/' /target/etc/locale.gen
    else
        printf 'en_US.UTF-8 UTF-8\nen_GB.UTF-8 UTF-8\n' > /target/etc/locale.gen
    fi
    chroot /target locale-gen
    printf 'LANG=en_US.UTF-8\n' > /target/etc/locale.conf
    printf 'KEYMAP=us\n' > /target/etc/vconsole.conf

    chroot /target ln -sf /usr/share/zoneinfo/UTC /etc/localtime

    if ! chroot /target id -u borea >/dev/null 2>&1; then
        chroot /target useradd -m -g users -G wheel -s /bin/bash borea
    fi
    printf 'borea:borea\nroot:root\n' | chroot /target chpasswd
    mkdir -p /target/etc/sudoers.d
    printf 'borea ALL=(ALL:ALL) NOPASSWD: ALL\n' > /target/etc/sudoers.d/10-borea
    chmod 0440 /target/etc/sudoers.d/10-borea

    chroot /target systemctl enable NetworkManager.service || :
    chroot /target systemctl enable sshd.service || :
}

probe_initramfs() {
    test -f /target/boot/vmlinuz-linux
    test -s /target/boot/initramfs-linux.img
}
do_initramfs() {
    mount_chroot
    if [ "$fs" = "btrfs" ]; then
        if [ -f /target/etc/mkinitcpio.conf ]; then
            if ! grep -q 'MODULES=.*btrfs' /target/etc/mkinitcpio.conf; then
                sed -i 's/^MODULES=(\(.*\))/MODULES=(\1 btrfs)/' /target/etc/mkinitcpio.conf
            fi
        fi
    fi
    chroot /target mkinitcpio -P
}

probe_bootloader() {
    test -f /target/boot/efi/EFI/BOOT/BOOTX64.EFI
    test -f /target/boot/efi/EFI/BOOT/limine.conf
    grep -q "guid(${boot_uuid})" /target/boot/efi/EFI/BOOT/limine.conf
}
do_bootloader() {
    mkdir -p /target/boot/efi/EFI/BOOT /target/boot/efi/EFI/borea /target/boot/limine
    if [ -f /target/usr/share/limine/BOOTX64.EFI ]; then
        cp /target/usr/share/limine/BOOTX64.EFI /target/boot/efi/EFI/BOOT/BOOTX64.EFI
        cp /target/usr/share/limine/BOOTX64.EFI /target/boot/efi/EFI/borea/BOOTX64.EFI
    fi
    cmdline_flags=""
    if [ "$fs" = "btrfs" ]; then
        cmdline_flags="rootflags=subvol=@"
    fi
    cat << EOF > /target/boot/efi/EFI/BOOT/limine.conf
timeout: 3

/Borea (Arch Linux)
    protocol: linux
    path: guid(${boot_uuid})/vmlinuz-linux
    module_path: guid(${boot_uuid})/initramfs-linux.img
    cmdline: root=UUID=${root_uuid} ${cmdline_flags} rw console=tty0 console=ttyS0,115200

/Borea fallback
    protocol: linux
    path: guid(${boot_uuid})/vmlinuz-linux
    module_path: guid(${boot_uuid})/initramfs-linux-fallback.img
    cmdline: root=UUID=${root_uuid} ${cmdline_flags} rw console=tty0 console=ttyS0,115200
EOF
    cp /target/boot/efi/EFI/BOOT/limine.conf /target/boot/limine/limine.conf
}

step storage_probe
step pacstrap
step system_config
step initramfs
step bootloader

sync
cleanup
trap - EXIT
record verified-bootable
